import { startStaticPreviewServer } from './StaticPreviewServer';
import { createLibraryApp } from '../routes/library/app';
import { ProjectRuntimeService } from '../services/ProjectRuntimeService';
import { ProjectFolderPicker } from '../services/ProjectFolderPicker';
import { ProjectCardPreviews } from '../services/ProjectCardPreviews';
import path from 'path';
import { HubDiscovery } from '../services/HubDiscovery';
import { HubNavigation } from '../services/HubNavigation';
import { ProjectLibrary, currentLibraryRoot } from '../services/ProjectLibrary';
import { StaticLibraryPreviews } from '../services/StaticLibraryPreviews';
import { closeListener, listenLocally } from './http';
import { hubPort } from './hubPort';
import { BrowserSessions } from './BrowserSessions';
import { DesignProfiles } from '../services/profiles/DesignProfiles';
import { ProfileVariants } from '../services/profiles/ProfileVariants';
import { getConfigManager } from '../services/ConfigManager';
import {
  parseCallerRunnerPaths,
  verifiedRunnerPaths,
} from '../cli/callerRunnerPaths';

import type { TelemetryService } from '../services/TelemetryService';

interface HubOptions {
  root?: string;
  port?: number;
  telemetry?: TelemetryService;
  uiDirectory?: string;
  isSourceSyncAllowed?: boolean;
}
export const startHubServer = async ({
  root = currentLibraryRoot(),
  port = hubPort(),
  telemetry,
  uiDirectory = path.resolve(__dirname, '../../src/ui/dist'),
  isSourceSyncAllowed = true,
}: HubOptions = {}) => {
  const discovery = await HubDiscovery.open(root);
  const claim = discovery.claim();
  if (claim.status === 'occupied') {
    discovery.close();
    return null;
  }
  const token = claim.token;
  const browserSessions = new BrowserSessions({ scope: root });
  let library: ProjectLibrary;
  try {
    library = await ProjectLibrary.open(root);
  } catch (error) {
    discovery.release(token);
    discovery.close();
    throw error;
  }
  const navigation = new HubNavigation();
  const previews = new StaticLibraryPreviews(library, startStaticPreviewServer);
  const runtime = new ProjectRuntimeService(library.registry);
  const cardPreviews = new ProjectCardPreviews({
    library,
    runtime,
    previews,
    telemetry,
  });
  const folderPicker = new ProjectFolderPicker();
  const profiles = new DesignProfiles({
    root,
    variants: new ProfileVariants({ library, previews }),
    telemetry,
    accountId: () =>
      getConfigManager().isAuthenticated()
        ? getConfigManager().getUserId()
        : undefined,
    runnerPaths: () => ({
      ...parseCallerRunnerPaths(process.env),
      ...verifiedRunnerPaths(
        getConfigManager().getConfiguredRunnerPaths(),
        'profile runner configuration',
      ),
    }),
  });
  const app = createLibraryApp({
    token,
    browserSessions,
    library,
    navigation,
    previews,
    runtime,
    cardPreviews,
    folderPicker,
    profiles,
    telemetry,
    uiDirectory,
  });
  let listener: Awaited<ReturnType<typeof listenLocally>> | undefined;
  try {
    listener = await listenLocally(app, port);
    discovery.publish({ token, port: listener.port });
    if (isSourceSyncAllowed) profiles.sourceSync.start();
  } catch (error) {
    if (listener) await closeListener(listener.server);
    navigation.close();
    await profiles.close();
    await cardPreviews.close();
    await previews.close();
    library.close();
    discovery.release(token);
    discovery.close();
    throw error;
  }
  const activeListener = listener;
  let isClosed = false;
  return {
    url: activeListener.url,
    token,
    library,
    close: async (): Promise<void> => {
      if (isClosed) return;
      isClosed = true;
      folderPicker.close();
      await profiles.close();
      navigation.close();
      await cardPreviews.close();
      await closeListener(activeListener.server);
      await previews.close();
      library.close();
      discovery.release(token);
      discovery.close();
    },
  };
};
